const adminListGames = `-- name: AdminListGames :many
WITH listed AS (
    SELECT session.session_id,
           session.room_id,
           room.room_code,
           session.game_id,
           session.engine_version,
           session.protocol_version,
           session.client_version,
           session.status,
           session.state_version,
           session.ownership_epoch,
           session.started_at,
           session.updated_at,
           COALESCE(progress.last_progress_at, session.updated_at)::timestamptz AS last_progress_at,
           (
               room.room_id IS NULL
               OR (session.status IN ('active', 'suspended') AND (
                   room.active_session_id IS DISTINCT FROM session.session_id
                   OR room.active_game_id IS DISTINCT FROM session.game_id
                   OR room.status <> 'playing'
               ))
           ) AS room_link_mismatch
    FROM game_sessions AS session
    LEFT JOIN party_rooms AS room ON room.room_id = session.room_id
    LEFT JOIN LATERAL (
        SELECT max(batch.committed_at)::timestamptz AS last_progress_at
        FROM game_session_event_batches AS batch
        WHERE batch.session_id = session.session_id
    ) AS progress ON true
    WHERE ($7::uuid IS NULL OR session.session_id = $7)
      AND ($8::uuid IS NULL OR session.room_id = $8)
      AND (cardinality($9::text[]) = 0 OR session.game_id = ANY($9::text[]))
      AND (cardinality($10::text[]) = 0 OR session.status = ANY($10::text[]))
      AND ($11::timestamptz IS NULL OR session.started_at >= $11)
      AND ($12::timestamptz IS NULL OR session.started_at <= $12)
      AND ($13::timestamptz IS NULL OR session.updated_at >= $13)
      AND ($14::timestamptz IS NULL OR session.updated_at <= $14)
)
SELECT session_id, room_id, room_code, game_id, engine_version, protocol_version, client_version, status, state_version, ownership_epoch, started_at, updated_at, last_progress_at, room_link_mismatch
FROM listed
WHERE (
    NOT $1::boolean
    OR listed.room_link_mismatch
)
AND (
    $2::uuid IS NULL
    OR ($3::text = 'updated_at' AND (
        ($4::text = 'ascending'
            AND (listed.updated_at > $5::timestamptz
                OR (listed.updated_at = $5::timestamptz AND listed.session_id > $2::uuid)))
        OR ($4::text = 'descending'
            AND (listed.updated_at < $5::timestamptz
                OR (listed.updated_at = $5::timestamptz AND listed.session_id < $2::uuid)))
    ))
    OR ($3::text = 'started_at' AND (
        ($4::text = 'ascending'
            AND (listed.started_at > $5::timestamptz
                OR (listed.started_at = $5::timestamptz AND listed.session_id > $2::uuid)))
        OR ($4::text = 'descending'
            AND (listed.started_at < $5::timestamptz
                OR (listed.started_at = $5::timestamptz AND listed.session_id < $2::uuid)))
    ))
    OR ($3::text = 'last_progress_at' AND (
        ($4::text = 'ascending'
            AND (listed.last_progress_at > $5::timestamptz
                OR (listed.last_progress_at = $5::timestamptz AND listed.session_id > $2::uuid)))
        OR ($4::text = 'descending'
            AND (listed.last_progress_at < $5::timestamptz
                OR (listed.last_progress_at = $5::timestamptz AND listed.session_id < $2::uuid)))
    ))
    OR ($3::text = 'session_id' AND (
        ($4::text = 'ascending' AND listed.session_id > $2::uuid)
        OR ($4::text = 'descending' AND listed.session_id < $2::uuid)
    ))
)
ORDER BY
    CASE WHEN $3::text = 'updated_at' AND $4::text = 'ascending' THEN listed.updated_at END ASC,
    CASE WHEN $3::text = 'updated_at' AND $4::text = 'descending' THEN listed.updated_at END DESC,
    CASE WHEN $3::text = 'started_at' AND $4::text = 'ascending' THEN listed.started_at END ASC,
    CASE WHEN $3::text = 'started_at' AND $4::text = 'descending' THEN listed.started_at END DESC,
    CASE WHEN $3::text = 'last_progress_at' AND $4::text = 'ascending' THEN listed.last_progress_at END ASC,
    CASE WHEN $3::text = 'last_progress_at' AND $4::text = 'descending' THEN listed.last_progress_at END DESC,
    CASE WHEN $4::text = 'ascending' THEN listed.session_id END ASC,
    CASE WHEN $4::text = 'descending' THEN listed.session_id END DESC
LIMIT $6
`

